cd /app && python - <<'EOF'
p='statements/meridale.py'
s=open(p).read()
a=s.index("def _amount")
b=s.index("def monthly_statement")
helpers='''_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "US/Mountain": "America/Denver",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}

_SUPPORTED = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
# locale -> (decimal, group, code before?)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True), "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        sign = -1 if m.group(1) in "-\\u2212" else 1
        if hours == 0:
            return "Etc/UTC"
        # POSIX Etc names invert the sign
        return f"Etc/GMT{'-' if sign > 0 else '+'}{hours}"
    return _LINKS.get(tz, tz)


def _locale(loc: str) -> str:
    tag = loc.split(".")[0].split("@")[0].replace("_", "-")
    if tag in _SUPPORTED:
        return tag
    lang = tag.split("-")[0]
    if lang in _SUPPORTED:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(n: str, indian: bool, sep: str, es: bool) -> str:
    if es and len(n) == 4:
        return n
    if indian and len(n) > 3:
        head, tail = n[:-3], n[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        return sep.join(parts + [tail])
    parts = []
    while len(n) > 3:
        parts.insert(0, n[-3:])
        n = n[:-3]
    parts.insert(0, n)
    return sep.join(parts)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    digits = _digits(currency)
    neg = value < 0
    s = f"{abs(value):.{digits}f}"
    ip, _, fp = s.partition(".")
    num = _group(ip, locale == "en-IN", grp, locale == "es")
    if digits:
        num += dec + fp
    if neg:
        num = "-" + num
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


'''
s=s[:a]+helpers+s[b:]
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
c=s.index("    first = date")
s=s[:c]+'''    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    nd = _digits(cur)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], nd) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, cur, locale)))
    total = sum((line.net for line in lines), Decimal(0))
    return Statement(merchant.id, cur, tuple(lines), total, _text(total, cur, locale))
'''
open(p,'w').write(s)
EOF
